describe(\"member suspension\", () => {
  it(\"keeps the membership and seat, blocks access, and reinstates idempotently\", async () => {
    const tenant = await createTenant(\"member-suspension\", \"growth\");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if ("'!target) throw new Error("fixture member missing");
    const events: string[] = [];
    const offs = [
      subscribe("member.suspended", (payload) => { events.push(payload.memberId); }),
      subscribe("member.reinstated", (payload) => { events.push(payload.memberId); }),
    ];
    try {
      const input = { orgId: tenant.org.id, memberId: target.id };
      const suspended = await memberService.suspendMember(tenant.actors.admin, input);
      expect(suspended).toMatchObject({ status: "suspended", role: target.role, archivedAt: null });
      expect(await memberService.suspendMember(tenant.actors.admin, input)).toEqual(suspended);
      expect(events).toEqual([target.id]);
      expect(await memberService.resolveActor(target.userId, tenant.org.id)).toBeNull();
      expect(await orgRepo.listOrgsForUser(target.userId)).toEqual([]);
      expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(4);
      expect((await usageRepo.recomputeUsage(tenant.org.id)).seatsUsed).toBe(4);
      expect((await memberService.listMembers(tenant.actors.admin, {
        orgId: tenant.org.id, limit: 100, cursor: null,
      })).items.find((member) => member.id === target.id)?.status).toBe("suspended");
      const reinstated = await memberService.reinstateMember(tenant.actors.admin, input);
      expect(reinstated.status).toBe("active");
      expect(await memberService.reinstateMember(tenant.actors.admin, input)).toEqual(reinstated);
      expect(events).toEqual([target.id, target.id]);
      expect(await memberService.resolveActor(target.userId, tenant.org.id)).toEqual(tenant.actors.member);
      expect((await orgRepo.listOrgsForUser(target.userId)).map((org) => org.id)).toContain(tenant.org.id);
      await memberService.removeMember(tenant.actors.admin, input);
      await expect(memberService.reinstateMember(tenant.actors.admin, input)).rejects.toBeInstanceOf(NotFoundError);
      await expect(memberService.suspendMember(tenant.actors.admin, input)).rejects.toBeInstanceOf(NotFoundError);
      expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(3);
    } finally {
      offs.forEach((off) => off());
    }
  });

  it("refuses self changes and higher roles, and excludes suspended owners from owner protection", async () => {
    const tenant = await createTenant("suspended-owners", "growth");
    const owner = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!owner || !admin) throw new Error("fixture member missing");
    for (const change of [memberService.suspendMember, memberService.reinstateMember]) {
      await expect(change(tenant.actors.owner, { orgId: tenant.org.id, memberId: owner.id })).rejects.toThrow(/yourself/);
      await expect(change(tenant.actors.admin, { orgId: tenant.org.id, memberId: owner.id })).rejects.toThrow(/outranks/);
    }
    await memberService.updateMemberRole(tenant.actors.owner, { orgId: tenant.org.id, memberId: admin.id, role: "owner" });
    await memberService.suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: admin.id });
    await expect(memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: owner.id })).rejects.toThrow(/at least one owner/);
    await expect(memberService.updateMemberRole(tenant.actors.owner, { orgId: tenant.org.id, memberId: owner.id, role: "admin" })).rejects.toThrow(/at least one owner/);
  });
});
